mapper.delete:
DELETE FROM sys_event_outbox
WHERE id IN (SELECT id FROM (
    SELECT id FROM sys_event_outbox
    WHERE service_name = #{serviceName}
      AND status = #{status}
      AND sent_time < #{sentTimeBefore}
    LIMIT #{limit}
) AS expired_ids)
